/* TRIP WATCH - an agentic p0pc0rn app, and the Skeleton Guide's agentic example. Tell it about a trip ("camping at Zion this Friday to
   Sunday") and close it: Juli turns your words into a place and dates in its next check, and a notice in her chat asks you to confirm
   them. Then, while p0pc0rn is open, it watches the US National Weather Service forecast and alerts for the trip's days, re-checks as
   they change, and brings what needs your eye to its review queue (with one notice in Juli's chat): strong wind, rain or snow, heat,
   cold, or an alert. Juli writes one line per trip from the forecast's own numbers (a line with any other number is left out, never
   shown) and answers your questions about a trip from the same forecast.
   Juli never works while the app is open: the phone's memory goes to the open app. The open app saves what you ask for; her work
   happens in the checks, the first one right after you close the app.
   The five parts of an agentic app (Skeleton Guide, "Two kinds of app"):
     goal      manifest.goal: keep an eye on the weather for my trips and tell me what changed
     notebook  K.notebook('trips'): confirmed = your trips; suspected = flags, Juli's lines and answers, trip suggestions (the review queue),
               your notes and questions waiting for Juli; grounding = each trip's forecast (NWS, with when it came); dismissed = what you
               waved off (raised again only if it gets worse)
     tasks     active (the open app): leave Juli a trip note or a question, pick a trip yourself, confirm. idle (K.agent): 'watch' reads your
               notes and questions with Juli, fetches, compares, flags and sums up; 'tidy' lets finished trips go
     reach     weather.nws, alerts.nws, geocode.openmeteo, and Juli (permissions.juli ["ask"])
     review    K.review(): flags and trip suggestions with their evidence. Only you add a trip.
   US only (NWS). Everything it keeps stays on this phone. */

// ===== SLOTS =====
const SL = window.SLOTS || {};
const sl = (v, n, d) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, n) : d);
const si = (v, lo, hi, d) => (v != null && v !== '' && Number.isFinite(+v) ? Math.max(lo, Math.min(hi, Math.round(+v))) : d);
const TITLE = sl(SL.title, 22, 'Trip Watch');
const ACCENT = /^#[0-9a-fA-F]{6}$/.test(SL.accent || '') ? SL.accent : '#30b0c7';
const WORD = sl(SL.trip_word, 14, 'trip').toLowerCase();
const WIND = si(SL.wind_mph, 10, 60, 25), RAIN = si(SL.rain_pct, 20, 100, 50), HOT = si(SL.hot_f, 70, 120, 90), COLD = si(SL.cold_f, -20, 50, 32);
const LEVELS = ['warnings', 'watches', 'all'], LEVEL = LEVELS.includes(SL.alert_level) ? SL.alert_level : 'watches';
const EXAMPLE = sl(SL.example, 60, 'Hiking at Zion this Saturday');
const cap = (s) => (s ? s[0].toUpperCase() + s.slice(1) : s);
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');

// ===== THE NOTEBOOK (on this phone) =====
const nb = K.notebook('trips', { max: 300 });
const trips = () => nb.list('confirmed', 'trip').filter((e) => e.data && e.data.place && K.isDay(e.data.start)).sort((a, b) => (a.data.start < b.data.start ? -1 : 1));
const forTrip = (id, kind) => nb.all.filter((e) => e.data && e.data.trip === id && (!kind || e.kind === kind));
const waiting = () => nb.all.filter((e) => e.shelf === 'suspected' && (e.kind === 'note' || e.kind === 'question' || e.kind === 'note!')).sort((a, b) => a.at - b.at);
const placeName = (p) => [p.name, p.region].filter(Boolean).join(', ');
const dates = (t) => (t.end && t.end !== t.start ? K.dayLabel(t.start) + ' – ' + K.dayLabel(t.end) : K.dayLabel(t.start));
const whatOf = (t) => sl(t.what, 30, WORD);
function badge() { if (window.p0) p0.app.badge(nb.review().length).catch(() => {}); }
async function post(n, ctx) {   // a short notice in Juli's chat, only from a check (in the open app you see it here)
  if (ctx.mode !== 'check' || !window.p0) return;
  try { await p0.chat.post(n); } catch (e) { /* too many this hour: it still shows in the app */ }
}

// ===== READING THE FORECAST (NWS: a day and a night period for about 7 days) =====
const dayOf = (p) => String(p.start || '').slice(0, 10);   // the trip place's own date (NWS gives its local time)
const inTrip = (t, p) => { const d = dayOf(p); return d >= t.start && d <= t.end; };
const windOf = (p) => { const n = (String(p.wind || '').match(/\d+/g) || []).map(Number), g = /gusts? (?:as high as |up to )?(\d+) mph/i.exec(p.detail || ''); return { mph: n.length ? Math.max(...n) : 0, gust: g ? +g[1] : 0 }; };
const tempF = (p) => (p.unit === 'C' ? Math.round(p.temp * 9 / 5 + 32) : +p.temp);
const wet = (p) => /rain|shower|snow|sleet|thunder|storm/i.test(p.short || '');
const sevOf = (a) => (a.severity === 'Extreme' || a.severity === 'Severe' || /warning|emergency/i.test(a.event) ? 'warning' : /watch/i.test(a.event) ? 'watch' : 'info');
const alertWorth = (a) => { const s = sevOf(a); return s === 'warning' || (s === 'watch' && LEVEL !== 'warnings') || LEVEL === 'all'; };
function alertInTrip(a, t) {   // an alert counts when its time overlaps the trip's days (no end time = still on)
  const from = Date.parse(t.start + 'T00:00:00'), to = Date.parse(K.addDays(t.end, 1) + 'T00:00:00');
  return (Date.parse(a.effective) || 0) < to && (Date.parse(a.ends) || Infinity) > from;
}
/** what in a trip's forecast needs the person's eye: [{key, type, value, sev, text}]; value = the reading that crossed the line */
function flagsFor(tr, fc) {
  const out = [];
  for (const p of fc.periods) {
    const d = dayOf(p) + (p.day ? '' : 'n'), w = windOf(p), top = Math.max(w.mph, w.gust), f = tempF(p);
    if (top >= WIND) out.push({ type: 'wind', day: d, value: top, sev: top >= WIND + 15 ? 'warning' : 'watch', text: `${p.name}: wind ${p.wind}${w.gust ? ', gusts to ' + w.gust + ' mph' : ''}` });
    if (wet(p) && (p.pop != null ? p.pop >= RAIN : /likely|heavy/i.test(p.short || ''))) out.push({ type: 'wet', day: d, value: p.pop != null ? p.pop : 0, sev: 'watch', text: `${p.name}: ${p.short}${p.pop != null ? ' (' + p.pop + '%)' : ''}` });
    if (p.day && f >= HOT) out.push({ type: 'hot', day: d, value: f, sev: f >= HOT + 10 ? 'warning' : 'watch', text: `${p.name}: high ${p.temp}°${p.unit}` });
    if (!p.day && f <= COLD) out.push({ type: 'cold', day: d, value: -f, sev: f <= COLD - 15 ? 'warning' : 'watch', text: `${p.name}: low ${p.temp}°${p.unit}` });
  }
  for (const a of fc.alerts) if (alertWorth(a)) out.push({ type: 'alert', day: String(a.id).slice(-60), value: 0, sev: sevOf(a), text: `${a.event}: ${a.headline || a.area}`.slice(0, 300) });
  return out.map((f) => Object.assign(f, { key: `flag:${tr.id}:${f.type}:${f.day}` }));
}
// a flag the person waved off comes back only when it is clearly worse (alerts: each one once)
const worse = (f, was) => f.type !== 'alert' && !!was && f.value >= (was.value || 0) + (f.type === 'wind' ? 10 : f.type === 'wet' ? 20 : 5);
function forecastText(fc) {
  const ps = fc.periods.map((p) => `- ${p.name} (${dayOf(p)}): ${p.temp}°${p.unit}, wind ${p.wind}${p.pop != null ? ', ' + p.pop + '% chance of rain or snow' : ''}, ${p.short}`).join('\n');
  const al = fc.alerts.length ? fc.alerts.map((a) => `- ${a.event}: ${a.headline || a.area}`).join('\n') : '- none';
  return `The US National Weather Service forecast for those days:\n${ps || '- not out yet'}\nActive alerts:\n${al}`;
}
const notIn = (m) => `${m.join(', ')} ${m.length > 1 ? 'are' : 'is'} not in the forecast`;
const tripLine = (t) => `A ${whatOf(t)} at ${placeName(t.place)}, ${t.start}${t.end !== t.start ? ' to ' + t.end : ''}.`;

// ===== YOUR WORDS -> A TRIP (Juli, in a check) =====
function nextDom(n) { for (let i = 1; i <= 62; i++) { const d = K.addDays(K.today(), i); if (+d.slice(8) === n) return d; } return K.addDays(K.today(), 10); }
function nextWeekend() { const dow = new Date().getDay(), sat = K.addDays(K.today(), (dow === 6 ? 0 : dow === 0 ? -1 : 6 - dow) + 7); return [sat, K.addDays(sat, 1)]; }   // the weekend after this one
const STATES = ('AL Alabama AK Alaska AZ Arizona AR Arkansas CA California CO Colorado CT Connecticut DE Delaware FL Florida GA Georgia HI Hawaii ID Idaho IL Illinois IN Indiana IA Iowa KS Kansas KY Kentucky '
  + 'LA Louisiana ME Maine MD Maryland MA Massachusetts MI Michigan MN Minnesota MS Mississippi MO Missouri MT Montana NE Nebraska NV Nevada NH New_Hampshire NJ New_Jersey NM New_Mexico NY New_York '
  + 'NC North_Carolina ND North_Dakota OH Ohio OK Oklahoma OR Oregon PA Pennsylvania RI Rhode_Island SC South_Carolina SD South_Dakota TN Tennessee TX Texas UT Utah VT Vermont VA Virginia WA Washington '
  + 'WV West_Virginia WI Wisconsin WY Wyoming DC District_of_Columbia').split(' ');
const stateName = (x) => { x = String(x || '').trim(); const i = STATES.indexOf(x.toUpperCase()); return i >= 0 && i % 2 === 0 ? STATES[i + 1].replace(/_/g, ' ') : x; };   // 'GA' -> 'Georgia'
function tripPrompt(note) {
  const d3 = nextDom(3), [sat, sun] = nextWeekend();
  return 'Turn the note into a trip for a weather app.\n' + K.calendar(21) + '\n' +
    '"This <day>" = the first such day after today; "this weekend" = the coming Saturday and Sunday (this one if today is a weekend day); "next weekend" = the weekend after that; "for N days" counts the first day; one day = the same start and end.\n' +
    'Reply with ONE JSON object and nothing else: {"place": "town or park name only", "region": "US state if said or known", "start": "YYYY-MM-DD", "end": "YYYY-MM-DD", "what": "1-3 words: hike, camping, wedding..."}\n' +
    'If the note has no place or no future date, reply {"none": "what is missing"}.\n' +
    'Examples:\n' +
    `We hike Yosemite on the 3rd -> {"place": "Yosemite", "region": "California", "start": "${d3}", "end": "${d3}", "what": "hike"}\n` +
    `Camping at Lake Tahoe next weekend -> {"place": "Lake Tahoe", "region": "California", "start": "${sat}", "end": "${sun}", "what": "camping"}\n` +
    'Our Zion trip last year was great -> {"none": "a past trip"}\n\n' +
    'Note: ' + note;
}
/** Juli reads a note: {trip: {what, start, end, places}} or {why}; throws when Juli can't answer */
async function readTrip(note) {
  const r = await K.ask(tripPrompt(note), { json: true });
  if (!r || r.none || typeof r.place !== 'string' || !r.place.trim()) return { why: r && r.none ? cap(String(r.none).slice(0, 60)) : "Juli couldn't find a place and a date in it" };
  const today = K.today();
  let start = K.isDay(r.start) ? r.start : null, end = K.isDay(r.end) && r.end >= (start || '') ? r.end : start;
  // your own words win over Juli's arithmetic in the plain cases: "today", "tomorrow", "on the 3rd" (no month named)
  const low = note.toLowerCase(), named = /\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b/.test(low), nth = /\b(\d{1,2})(?:st|nd|rd|th)\b/.exec(low);
  const plain = /\btoday\b/.test(low) ? today : /\btomorrow\b/.test(low) ? K.addDays(today, 1) : nth && !named && +nth[1] >= 1 && +nth[1] <= 31 ? nextDom(+nth[1]) : null;
  if (plain && start && plain !== start) { end = K.addDays(plain, Math.max(0, K.daysFrom(start, end))); start = plain; }
  if (!start) return { why: 'Say when it is, like "this Saturday"' };
  if (end < today) return { why: 'That date has passed' };
  if (start < today) start = today;
  if (K.daysFrom(start, end) > 13) end = K.addDays(start, 13);
  let places;
  try { places = ((await p0.fetch('geocode.openmeteo', { name: String(r.place).slice(0, 60) })).results || []).filter((x) => x.cc === 'US'); }
  catch (e) { throw Object.assign(new Error("couldn't reach the place search"), { code: 'OFFLINE' }); }   // the note waits for the next check
  const rg = stateName(r.region).toLowerCase(), same = (x) => !!rg && (x.region || '').toLowerCase() === rg;
  places = places.filter(same).concat(places.filter((x) => !same(x))).slice(0, 3);
  if (!places.length) return { why: `No US place called ${String(r.place).slice(0, 30)}` };
  return { trip: { what: sl(r.what, 30, ''), start, end, places } };
}

// ===== IDLE TASK 1: watch (the host runs it while p0pc0rn is open, first right after you close the app; the open app runs it too, without Juli) =====
async function watch(ctx) {
  const juli = ctx.mode === 'check';   // Juli works only in a check: the open app keeps the phone's memory
  if (juli) await readNotes(ctx);
  const today = K.today(), list = trips().filter((tr) => tr.data.end >= today), offline = new Set(); let active = false, fresh = 0, looked = 0;
  for (const tr of list) {
    const t = tr.data, inDays = K.daysFrom(today, t.start);
    if (inDays > 6) continue;   // not in the forecast yet (NWS looks about 7 days ahead)
    if (ctx.left() < 15) break;
    let w, al;
    try { [w, al] = await Promise.all([p0.fetch('weather.nws', { lat: t.place.lat, lon: t.place.lon }), p0.fetch('alerts.nws', { lat: t.place.lat, lon: t.place.lon })]); }
    catch (e) { offline.add(tr.id); ctx.log(`Couldn't reach the weather service for ${t.place.name}`); continue; }
    looked++;
    const fc = { periods: (w.periods || []).filter((p) => inTrip(t, p)), alerts: (al.alerts || []).filter((a) => alertInTrip(a, t)).slice(0, 6), at: w.fetchedAt || Date.now() };
    const sig = JSON.stringify([fc.periods.map((p) => [p.name, p.temp, p.wind, p.pop, p.short, p.detail]), fc.alerts.map((a) => a.id)]);
    const old = nb.get('fc:' + tr.id), changed = !old || !old.data || old.data.sig !== sig || !!(old.data && old.data.unsummed);
    // flags: new or worse ones go to the review queue (and, unseen, one notice each in Juli's chat); cleared ones go away
    const flags = flagsFor(tr, fc), keys = new Set(flags.map((f) => f.key)), raised = [];
    for (const f of flags) {
      const was = nb.get(f.key), fields = { kind: 'flag', title: `${cap(whatOf(t))} · ${t.place.name}`, text: f.text, data: { trip: tr.id, type: f.type, value: f.value, sev: f.sev }, evidence: [{ source: 'NWS forecast', at: fc.at }] };
      let raise = false;
      if (!was) { nb.add(Object.assign({ key: f.key, review: true }, fields)); raise = true; }
      else if (was.shelf === 'dismissed') { if (worse(f, was.data)) { nb.put(f.key, Object.assign({ shelf: 'suspected', review: true }, fields)); raise = true; } }
      else { raise = worse(f, was.data); nb.put(f.key, Object.assign(raise ? { review: true } : {}, fields)); }
      if (raise) { fresh++; raised.push(f); ctx.log((was ? 'Worse: ' : 'New: ') + f.text + ' at ' + t.place.name); }
    }
    if (raised.length) await post({ title: `${TITLE} · ${t.place.name}`, severity: raised.some((f) => f.sev === 'warning') ? 'warning' : 'watch',   // one notice for the trip
      text: `${raised.map((f) => f.text).join('; ')}. For your ${whatOf(t)}, ${dates(t)}. Data: NWS.` }, ctx);
    for (const e of forTrip(tr.id, 'flag')) if (e.shelf === 'suspected' && !keys.has(e.key)) { nb.remove(e.id); ctx.log('Cleared: ' + e.text + ' at ' + t.place.name); }
    // Juli's line for the trip when the forecast changed (in the open app it waits for the next check: 'unsummed')
    const summed = changed && fc.periods.length && juli && ctx.left() > 25 ? await brief(tr, fc, ctx) : !changed;
    nb.put('fc:' + tr.id, { shelf: 'grounding', kind: 'forecast', title: 'Forecast for ' + t.place.name, data: Object.assign({ trip: tr.id, sig, unsummed: !summed && !!fc.periods.length }, fc), evidence: [{ source: 'NWS', at: fc.at }] });
    if (inDays <= 2 || flags.length) active = true;
  }
  if (juli) await answerQuestions(ctx, offline);
  badge();
  ctx.log(!list.length ? 'Nothing to watch yet' : !looked ? `${plural(list.length, WORD)}, not in the forecast yet` : `Checked ${plural(looked, WORD)}` + (fresh ? `: ${fresh} new to look at` : ': nothing new'));
  return { active: active || waiting().some((e) => e.kind !== 'note!') };
}
async function brief(tr, fc, ctx) {   // Juli's one line for a trip: kept only if every number in it is in the forecast. -> true when done
  const t = tr.data;
  let line = '';
  try { line = (await K.ask(`${tripLine(t)}\n${forecastText(fc)}\n\nIn ONE short sentence, say what matters most about the weather for this ${whatOf(t)}. Use only numbers from the forecast above. No other text.`)).replace(/\s+/g, ' ').trim(); }
  catch (e) { ctx.log(`Juli couldn't sum up ${t.place.name} this time`); return false; }
  if (!line) return true;
  const chk = K.facts(line, fc);
  if (!chk.ok) { ctx.log(`Left out Juli's line for ${t.place.name}: ${notIn(chk.missing)}`); return true; }
  nb.put('brief:' + tr.id, { shelf: 'suspected', kind: 'brief', title: 'Juli on ' + t.place.name, text: line.slice(0, 240), data: { trip: tr.id }, evidence: [{ source: 'Juli, from the NWS forecast', at: Date.now() }] });
  ctx.log('Juli summed up ' + t.place.name);
  return true;
}
async function readNotes(ctx) {   // the trip notes you left: Juli reads each one; a suggestion waits for your tap (and a notice says so)
  for (const e of nb.list('suspected', 'note').reverse().slice(0, 3)) {
    if (ctx.left() < 30) break;
    const note = String((e.data && e.data.note) || e.title || '');
    let r;
    try { r = await readTrip(note); }
    catch (x) { if (x && x.code === 'NOT_DOWNLOADED') { nb.put(e.id, { kind: 'note!', text: 'Juli is not downloaded: pick the place and day yourself.' }); continue; }
      ctx.log(x && x.code === 'OFFLINE' ? "Couldn't reach the place search: Juli tries your note again next time" : "Juli couldn't read a note this time: " + note.slice(0, 50)); break; }
    if (!r.trip) { nb.put(e.id, { kind: 'note!', text: r.why }); ctx.log(`Juli couldn't make a ${WORD} of: ${note.slice(0, 50)}`); continue; }
    nb.remove(e.id);
    const s = nb.add({ kind: 'trip?', review: true, title: `Add this ${WORD}?`, text: `${cap(r.trip.what || WORD)} · ${dates(r.trip)}`, data: Object.assign({ pick: 0 }, r.trip), evidence: [{ source: 'Juli, from your words', at: Date.now(), note }] });
    ctx.log(`Juli read your note: ${s.text}, ${placeName(r.trip.places[0])}`);
    await post({ title: `${TITLE}: a ${WORD} to confirm`, severity: 'info', text: `${s.text}, ${placeName(r.trip.places[0])}. Open ${TITLE} to add it.` }, ctx);
  }
}
async function answerQuestions(ctx, offline) {   // your questions about a trip, from its newest forecast (fetched in this same check)
  for (const e of nb.list('suspected', 'question').reverse().slice(0, 2)) {
    if (ctx.left() < 20) break;
    const tr = nb.get((e.data || {}).trip), q = String((e.data && e.data.q) || e.title || '');
    if (!tr) { nb.remove(e.id); continue; }
    if (offline.has(tr.id)) continue;   // its forecast couldn't be fetched this time: the question waits
    const fc = (nb.get('fc:' + tr.id) || {}).data, t = tr.data;
    let text;
    if (!fc || !fc.periods || !fc.periods.length) text = 'The forecast for these days is not out yet: it reaches about 7 days ahead.';
    else {
      try { text = (await K.ask(`${tripLine(t)}\n${forecastText(fc)}\n\nQuestion: ${q}\nAnswer in at most three short sentences, using only the forecast above. If it does not say, say so.`)).replace(/\s+/g, ' ').trim(); }
      catch (x) { ctx.log(`Juli couldn't answer a question about ${t.place.name} this time`); break; }
      const chk = K.facts(text, { q, fc });
      if (!text || !chk.ok) { if (text) ctx.log(`Left out an answer about ${t.place.name}: ${notIn(chk.missing)}`); text = "Juli's answer used a number that isn't in the forecast, so it isn't shown. Ask another way."; }
    }
    for (const a of nb.list('suspected', 'answer').filter((x) => x.data && x.data.trip === tr.id).slice(2)) nb.remove(a.id);   // keep the newest three
    nb.put(e.id, { kind: 'answer', text: text.slice(0, 600), evidence: [{ source: 'Juli, from the NWS forecast', at: Date.now() }] });
    ctx.log(`Juli answered your question about the ${whatOf(t)} at ${t.place.name}`);
    await post({ title: `${TITLE}: your question`, severity: 'info', text: `${q.slice(0, 120)}: ${text.slice(0, 300)}` }, ctx);
  }
}

// ===== IDLE TASK 2: tidy (a trip leaves the day after it ends, with everything kept for it) =====
async function tidy(ctx) {
  const today = K.today();
  for (const tr of trips()) if (tr.data.end < today) { for (const e of forTrip(tr.id)) nb.remove(e.id); nb.remove(tr.id); ctx.log(`The ${whatOf(tr.data)} at ${tr.data.place.name} is over: let go`); }
  for (const e of nb.list('suspected', 'trip?')) if (Date.now() - e.at > 7 * 864e5) nb.remove(e.id);   // a suggestion nobody answered goes after a week
  nb.prune(); badge();
  return { active: false };
}

const juliWork = () => waiting().some((e) => e.kind === 'note' || e.kind === 'question') || nb.list('grounding', 'forecast').some((e) => e.data && e.data.unsummed);
K.agent({ goal: 'Keep an eye on the weather for my trips', budgetS: 95, tasks: [{ id: 'watch', every: 60, run: watch, due: juliWork }, { id: 'tidy', every: 720, run: tidy }] });   // due: Juli has work waiting -> the next check

// ===== ACTIVE TASKS (the open app): leave Juli a note or a question, pick a trip yourself, confirm =====
const ui = { text: '', busy: '', manual: null, open: null, ask: null, askOpen: false, q: '', contentH: 900 };
function leaveNote() {   // the open app keeps your words; Juli reads them in the next check, right after you close Trip Watch
  const note = ui.text.trim().slice(0, 300);
  if (note.length < 4) return;
  nb.add({ kind: 'note', title: note, data: { note }, evidence: [{ source: 'You', at: Date.now() }] });
  ui.text = ''; K.blurInputs(); K.sfx('pop');
  K.toast(`Saved. Close ${TITLE} and Juli reads it`, { tone: 'good', icon: 'sparkle', ms: 3200 });
}
function leaveQuestion(tr) {
  const q = ui.q.trim().slice(0, 200);
  if (q.length < 3) return;
  nb.add({ kind: 'question', title: q, data: { trip: tr.id, q }, evidence: [{ source: 'You', at: Date.now() }] });
  ui.q = ''; ui.askOpen = false; K.blurInputs(); K.sfx('pop');
  K.toast(`Saved. Close ${TITLE} and Juli answers it`, { tone: 'good', icon: 'sparkle', ms: 3200 });
}
function confirmTrip(e) {   // the person's yes (a tap): the trip goes on the confirmed shelf, and the app looks at its forecast at once
  const d = e.data || {}, pl = (d.places || [])[d.pick || 0]; if (!pl) return;
  nb.confirm(e.id, { kind: 'trip', title: `${cap(d.what || WORD)} at ${pl.name}`, text: dates(d), data: { place: { name: pl.name, region: pl.region || '', lat: pl.lat, lon: pl.lon }, start: d.start, end: d.end, what: d.what || '' },
    evidence: [{ source: 'Added by you', at: Date.now() }] });
  K.sfx('success'); K.toast(`Watching ${pl.name}`, { tone: 'good', icon: 'check' }); badge();
  K.agent.run('watch');
}
function removeTrip(tr) { for (const e of forTrip(tr.id)) nb.remove(e.id); nb.remove(tr.id); K.agent.log(`You removed the ${whatOf(tr.data)} at ${tr.data.place.name}`); badge(); K.sfx('back'); }
async function manualSearch() {
  const m = ui.manual; if (!m || m.query.trim().length < 2 || ui.busy) return;
  if (!window.p0) { K.toast('Open this app in p0pc0rn to look up places', { tone: 'warn' }); return; }
  K.blurInputs(); ui.busy = 'Finding places…';
  try { m.results = ((await p0.fetch('geocode.openmeteo', { name: m.query.trim() })).results || []).filter((x) => x.cc === 'US').slice(0, 4); if (!m.results.length) K.toast('No US place with that name', { tone: 'warn' }); }
  catch (e) { K.toast("Couldn't search for places", { tone: 'bad' }); }
  ui.busy = '';
}
function manualAdd(pl) {
  const m = ui.manual, start = K.addDays(K.today(), m.start), end = K.addDays(start, m.days - 1);
  confirmTrip(nb.add({ kind: 'trip?', title: 'Your ' + WORD, data: { what: '', start, end, places: [pl], pick: 0 } }));
  ui.manual = null;
}
function onReview(act) {
  const e = act.entry;
  if (e.kind === 'trip?') { if (act.action === 'yes') confirmTrip(e); else { nb.remove(e.id); K.sfx('back'); badge(); } return; }
  if (act.action === 'no') { nb.dismiss(e.id); K.sfx('tap'); badge(); return; }   // "Got it": raised again only if it gets worse
  if (act.action === 'ask') { const tr = nb.get((e.data || {}).trip); if (tr) { ui.ask = tr.id; ui.askOpen = true; ui.q = ''; } }
}

// ===== DRAWING (the open app only: an unseen check never gets here) =====
function setup() {
  K.setup({ mode: 'dark', accent: ACCENT });
  K.scene('main', drawMain);
  if (window.p0 && p0.mode === 'run' && trips().length && Date.now() - K.agent.last('watch') > 30 * 60e3) K.agent.run('watch');   // a fresh look when it opens (no Juli)
}
function draw() { K.render(); ui.askOpen = K.sheet('ask', ui.askOpen, 400, drawAsk); }

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.darken(ACCENT, 0.84), glow: [{ x: K.W * 0.15, y: 90, r: 280, color: K.alpha(ACCENT, 0.16) }] });
  const n = trips().length, rv = nb.review().length;
  const sub = n ? `Watching ${plural(n, WORD)}` + (rv ? ` · ${rv} to look at` : '') : `Tell it about a ${WORD}`;
  const top = K.navBar.top(sub) + 8, clipY = K.navBar.bottom(), x = K.S.l, w = K.W - 2 * K.S.l;
  const off = K.scroll('main', 0, clipY, K.W, K.H - clipY, ui.contentH);
  K.clip(0, clipY, K.W, K.H - clipY, () => { ui.contentH = body(x, top - off, w) + off - top + 40; });
  const tap = K.navBar(TITLE, off, { sub, right: n ? { id: 'refresh', icon: 'refresh' } : undefined });
  if (tap === 'refresh' && !K.agent.busy()) K.agent.run('watch').then(() => K.toast('Checked', { tone: 'good', icon: 'refresh', ms: 1200 }));
}

function body(x, y, w) {
  const y0 = y, sevN = (e) => (e.kind === 'trip?' ? 0 : (e.data || {}).sev === 'warning' ? 1 : 2);   // suggestions first, then warnings, then by day
  const rv = nb.review().sort((a, b) => sevN(a) - sevN(b) || String(a.key || '').localeCompare(String(b.key || '')));
  if (rv.length) {   // 1. the review queue
    K.text('TO LOOK AT', x, y + 14, 'label', K.C.text2); y += 26;
    const r = K.review('rv', x, y, w, rv, {
      yes: (e) => (e.kind === 'trip?' ? 'Add ' + WORD : null),
      no: (e) => (e.kind === 'trip?' ? 'Not this' : 'Got it'),
      ask: (e) => e.kind === 'flag',
      color: (e) => (e.kind === 'trip?' ? ACCENT : (e.data || {}).sev === 'warning' ? K.C.bad : K.C.warn),
      extraH: (e) => (e.kind === 'trip?' ? 44 * Math.min(3, ((e.data || {}).places || []).length) + 4 : 0),
      extra: drawPlaces,
    });
    if (r.act) onReview(r.act);
    y += r.h + 6;
  }
  y = waitBox(x, y, w);   // 2. what waits for Juli
  y = addBox(x, y, w);   // 3. add a trip
  const list = trips();   // 4. your trips
  if (list.length) { K.text(('Your ' + WORD + 's').toUpperCase(), x, y + 18, 'label', K.C.text2); y += 30; for (const tr of list) y = tripCard(tr, x, y, w) + 10; }
  else if (!rv.length && !ui.manual && !waiting().length) y += K.empty(K.W / 2, y + 6, 'compass', `No ${WORD}s yet`, 'Say where and when above. It watches the weather for those days and tells you what changed.', { w: w - 40 }) + 10;
  const logs = K.agent.logs().slice(0, 6);   // 5. what the agent did
  if (logs.length) {
    K.text(('What ' + TITLE + ' did').toUpperCase(), x, y + 18, 'label', K.C.text2); y += 30;
    const lh = 42; K.card(x, y, w, logs.length * lh + 8, { r: 16 });
    logs.forEach((l, i) => { const ly = y + 4 + i * lh; if (i) K.line(x + 14, ly, x + w - 14, ly, K.C.line, 1); K.text(l.text, x + 14, ly + 19, 'footnote', K.C.text, { maxW: w - 28 }); K.text(K.fmt.ago(l.at) + (l.n > 1 ? ` · ${l.n} times` : ''), x + 14, ly + 35, 'caption', K.C.text3); });
    y += logs.length * lh + 18;
  }
  y += K.para(`Forecast and alerts: US National Weather Service. Juli works on your notes and questions after you close ${TITLE}, and her lines are checked against the forecast's own numbers. Only you add a ${WORD}. ${TITLE} works while p0pc0rn is open.`, x, y + 8, w, 'caption', K.C.text3) + 12;
  return y - y0;
}

function drawPlaces(e, x, y, w) {   // inside a suggestion card: which place (the search can find more than one)
  const d = e.data || {};
  (d.places || []).slice(0, 3).forEach((p, i) => {
    const ry = y + i * 44, on = (d.pick || 0) === i;
    K.rect(x, ry, w, 38, { r: 10, fill: on ? K.alpha(ACCENT, 0.2) : K.alpha(K.C.text, 0.05) });
    K.icon(on ? 'checkCircle' : 'pin', x + 18, ry + 19, 16, on ? ACCENT : K.C.text3);
    K.text(placeName(p), x + 36, ry + 24, 'subhead', K.C.text, { maxW: w - 48 });
    K.registerControl('place:' + e.id + ':' + i, x, ry, w, 38);
    if (!on && K.tapIn(x, ry, w, 38)) { nb.put(e.id, { data: Object.assign({}, d, { pick: i }) }); K.sfx('select'); }
  });
}

function waitBox(x, y, w) {   // your notes and questions waiting for Juli (and the ones she couldn't use)
  const list = waiting(); if (!list.length) return y;
  K.text('WAITING FOR JULI', x, y + 18, 'label', K.C.text2); y += 28;
  for (const e of list) {
    const tr = e.kind === 'question' ? nb.get((e.data || {}).trip) : null;
    const sub = e.kind === 'note!' ? e.text || "Juli couldn't use it" : e.kind === 'question' ? `A question about ${tr ? tr.data.place.name : 'a trip'}` : `A ${WORD} note`;
    const th = K.paraHeight(e.title || '', w - 92, 'callout', { maxLines: 3 }), h = th + 46;
    K.card(x, y, w, h, { r: 14 });
    K.icon(e.kind === 'note!' ? 'alert' : 'sparkle', x + 22, y + 22, 16, e.kind === 'note!' ? K.C.warn : ACCENT);
    K.para(e.title || '', x + 42, y + 8, w - 92, 'callout', K.C.text, { maxLines: 3 });
    K.text(sub, x + 42, y + th + 30, 'caption', e.kind === 'note!' ? K.C.warn : K.C.text3, { maxW: w - 92 });
    if (K.iconButton('wrm:' + e.id, x + w - 26, y + h / 2, 34, 'trash', { style: 'plain', color: K.C.text3 })) { nb.remove(e.id); K.sfx('back'); }
    y += h + 8;
  }
  y += K.para(list.some((e) => e.kind !== 'note!') ? `Juli works on these as soon as you close ${TITLE} (not while it's open: the phone's memory goes to the open app). A notice in her chat says when.` : '', x, y + 2, w, 'caption', K.C.text3) + 8;
  return y;
}

function addBox(x, y, w) {
  K.text(('Add a ' + WORD).toUpperCase(), x, y + 18, 'label', K.C.text2); y += 28;
  if (ui.manual) return manualBox(x, y, w);
  ui.text = K.input('add', x, y, w, 48, ui.text, { placeholder: EXAMPLE, icon: 'compass', onEnter: leaveNote });
  y += 58;
  const bw = (w - 8) / 2;
  if (K.button('add-juli', x, y, bw, 44, 'Give it to Juli', { style: 'primary', icon: 'sparkle', disabled: ui.text.trim().length < 4 })) leaveNote();
  if (K.button('add-self', x + bw + 8, y, bw, 44, 'Pick it myself', { style: 'secondary', icon: 'pin' })) ui.manual = { query: ui.text.trim().slice(0, 60), results: null, start: 0, days: 1 };
  return y + 60;
}

function manualBox(x, y, w) {
  const m = ui.manual;
  m.query = K.input('mq', x, y, w - 96, 48, m.query, { placeholder: 'Town or park (US)', icon: 'pin', onEnter: manualSearch });
  if (K.button('mfind', x + w - 86, y, 86, 48, ui.busy ? '…' : 'Find', { style: 'primary', disabled: !!ui.busy })) manualSearch();
  y += 60;
  K.text('FIRST DAY', x, y + 14, 'label', K.C.text3); y += 22;
  const labels = [0, 1, 2, 3, 4].map((i) => (i === 0 ? 'Today' : i === 1 ? 'Tmrw' : K.dayName(K.addDays(K.today(), i), true)));
  m.start = K.segmented('mstart', x, y, w, labels, m.start); y += 46;
  K.text('DAYS', x, y + 20, 'label', K.C.text3);
  m.days = K.stepper('mdays', x + w - 128, y + 4, m.days, { min: 1, max: 7, show: true }); y += 46;
  for (const [i, p] of (m.results || []).entries()) {
    const row = K.listRow('mres' + i, x, y, w, 56, { title: p.name, sub: [p.region, 'tap to add'].filter(Boolean).join(' · '), icon: 'pin', iconColor: ACCENT, chevron: true, r: 14 });
    if (row.tap) manualAdd(p);
    y += 62;
  }
  if (K.button('mcancel', x, y + 2, w, 42, 'Cancel', { style: 'ghost' })) { ui.manual = null; K.blurInputs(); }
  return y + 54;
}

function tripCard(tr, x, y, w) {
  const t = tr.data, today = K.today(), inDays = K.daysFrom(today, t.start), open = ui.open === tr.id;
  const fc = (nb.get('fc:' + tr.id) || {}).data, br = nb.get('brief:' + tr.id), flags = forTrip(tr.id, 'flag').filter((e) => e.shelf === 'suspected');
  const when = t.start <= today ? 'Now' : inDays === 1 ? 'Tomorrow' : `In ${inDays} days`;
  const status = !fc ? (inDays > 6 ? 'Forecast from ' + K.dayLabel(K.addDays(t.start, -6)) : 'Not checked yet') : flags.length ? plural(flags.length, 'thing') + ' to look at' : 'Nothing to look at';
  const tw = w - 32, brH = br && br.text ? K.paraHeight(br.text, tw, 'callout', { maxLines: 4 }) + 26 : 0;
  const rows = open && fc ? fc.periods.slice(0, 14) : [], rowsH = rows.length ? rows.length * 46 + 6 : open ? 30 : 0;
  const ans = open ? nb.list('suspected', 'answer').filter((e) => e.data && e.data.trip === tr.id).slice(0, 3) : [];
  const ansH = ans.reduce((s, e) => s + K.paraHeight(e.text || '', tw, 'footnote', { maxLines: 5 }) + 34, 0);
  const h = 98 + brH + rowsH + ansH + 54;
  K.card(x, y, w, h, { r: 18 });
  K.text(`${cap(whatOf(t))} at ${t.place.name}`, x + 16, y + 30, 'headline', K.C.text, { maxW: w - 40 - K.chipWidth(when) });
  K.chip(x + w - 16 - K.chipWidth(when), y + 14, when, { color: inDays <= 1 ? K.C.warn : ACCENT });
  K.text(dates(t) + (t.place.region ? ' · ' + t.place.region : ''), x + 16, y + 52, 'subhead', K.C.text2, { maxW: tw });
  K.icon(flags.length ? 'alert' : fc ? 'checkCircle' : 'clock', x + 24, y + 78, 16, flags.length ? K.C.warn : fc ? K.C.good : K.C.text3);
  K.text(status + (fc ? ' · checked ' + K.fmt.ago(fc.at) : ''), x + 40, y + 83, 'footnote', K.C.text3, { maxW: w - 56 });
  let yy = y + 98;
  if (brH) { K.para(br.text, x + 16, yy, tw, 'callout', K.C.text, { maxLines: 4 }); yy += brH - 26; K.text('Juli, from the NWS forecast · ' + K.fmt.ago(br.upd), x + 16, yy + 16, 'caption', K.C.text3); yy += 26; }
  if (open && !rows.length) { K.text(inDays > 6 ? 'The forecast does not reach these days yet.' : 'No forecast yet.', x + 16, yy + 18, 'footnote', K.C.text3); yy += 30; }
  rows.forEach((p, i) => {
    const ry = yy + i * 46; if (i) K.line(x + 16, ry, x + w - 16, ry, K.C.line, 1);
    K.icon(wet(p) ? 'rain' : /cloud|fog/i.test(p.short || '') ? 'cloud' : p.day ? 'sun' : 'moon', x + 26, ry + 23, 16, ACCENT);
    K.text(p.name, x + 44, ry + 20, 'subhead', K.C.text, { maxW: w - 130 });
    K.text(`${p.short}${p.pop != null ? ' · ' + p.pop + '%' : ''} · ${p.wind}`, x + 44, ry + 37, 'caption', K.C.text3, { maxW: w - 130 });
    K.text(p.temp + '°' + p.unit, x + w - 16, ry + 29, 'headline', K.C.text, { align: 'right' });
  });
  if (rows.length) yy += rowsH;
  for (const e of ans) { K.text(e.title, x + 16, yy + 16, 'subhead', K.C.text2, { maxW: tw }); yy += 24 + K.para(e.text || '', x + 16, yy + 22, tw, 'footnote', K.C.text, { maxLines: 5 }) + 10; }
  const bw = (tw - 16) / 3, by = y + h - 52;
  if (K.button('ask:' + tr.id, x + 16, by, bw, 38, 'Ask Juli', { style: 'tinted', icon: 'chat' })) { ui.ask = tr.id; ui.askOpen = true; ui.q = ''; }
  if (K.button('open:' + tr.id, x + 24 + bw, by, bw, 38, open ? 'Less' : 'Forecast', { style: 'secondary', icon: open ? 'chevronUp' : 'chevronDown' })) ui.open = open ? null : tr.id;
  if (K.button('rm:' + tr.id, x + 32 + 2 * bw, by, bw, 38, 'Remove', { style: 'ghost', icon: 'trash' })) removeTrip(tr);
  return y + h;
}

function drawAsk(x, y, w, h) {   // a question for Juli about one trip: kept, and answered in the next check (after you close the app)
  const tr = nb.get(ui.ask); if (!tr) return false;
  const px = 20, pw = w - 40; let yy = y + 34;
  K.text(`Ask about the ${whatOf(tr.data)} at ${tr.data.place.name}`, px, yy, 'headline', K.C.text, { maxW: pw }); yy += 20;
  K.text(dates(tr.data), px, yy, 'footnote', K.C.text3); yy += 14;
  ui.q = K.input('q', px, yy, pw, 48, ui.q, { placeholder: 'Is Sunday better for it?', icon: 'chat', onEnter: () => leaveQuestion(tr) }); yy += 58;
  if (K.button('qgo', px, yy, pw, 46, 'Give it to Juli', { style: 'primary', icon: 'send', disabled: ui.q.trim().length < 3 })) leaveQuestion(tr);
  yy += 58;
  K.para(`Juli answers from the newest forecast as soon as you close ${TITLE}; the answer shows on the ${WORD} and in her chat.`, px, yy, pw, 'footnote', K.C.text3, { maxLines: 4 });
  if (K.button('qdone', px, y + h - 64, pw, 44, 'Done', { style: 'ghost' })) { K.blurInputs(); return false; }
}
